        result = CLP_NOGOOD;
      }
      if (coreSize < (warriors * separation)) {
        print_usage(options);
        errout(coreSizeTooSmall);
        result = CLP_NOGOOD;
      }
      if (SWITCH_F) {
	char   *idx;
	useExtRNG = 0;
	SWITCH_Fnum = 0;
	for (idx = SWITCH_F; *idx; ++idx) {
	  useExtRNG |= !isdigit(*idx);
	  SWITCH_Fnum *= 10;
	  SWITCH_Fnum += (unsigned char)(*idx) - '0';
	}
	if (!useExtRNG && separation > SWITCH_Fnum) {
	  print_usage(options);
	  errout(FLessThand);
	  result = CLP_NOGOOD;
	} else {
	    if (SWITCH_Fnum < 0) SWITCH_Fnum *= -1;
	}
      }
      set_reg('W', (long) warriors);
      for (i = 1; i <= warriors; ++i) {
        set_reg('S', (long) i);
        if (eval_expr(SWITCH_eq, &dummy) < OK_EXPR) {
          print_usage(options);
          errout(badScoreFormula);
          result = CLP_NOGOOD;
          break;
        }
      }
#ifdef PSPACE
      if (pSpaceSize == 0)        /* make default, at least 1/16th of coresize */
        for (i = 16; i > 0; --i)
          if (!(coreSize % i)) {
            pSpaceSize = coreSize / i;
            break;
          }
      if (pSpaceSize > coreSize) {
	print_usage(options);
	errout(pSpaceTooBig);
	result = CLP_NOGOOD;
      }
#endif
#ifdef PERMUTATE
      if (SWITCH_P) {
	if (warriors != 2) {
	  print_usage(options);
	  errout(permutateMultiWarrior);
	  result = CLP_NOGOOD;
	} else if (rounds < 0) /* all possible combinations */
	    rounds = 2*coreSize-4*separation+2;
      } else if (rounds < 0 )
	rounds = DEFAULTROUNDS;
#endif
#ifdef RWLIMIT
      if (readLimit == 0)
	  readLimit = coreSize;
      if (writeLimit == 0)
	  writeLimit = coreSize;
      if (readLimit < 1 || writeLimit < 1 || coreSize % readLimit != 0 || coreSize % writeLimit != 0) {
	  print_usage(options);
	  errout(badRWLimit);
	  result = CLP_NOGOOD;
      }
#endif
      /* further checks of the values */

#ifndef OS2PMGRAPHX                /* jk - we can load files after the fact... */
      if (warrior[0].fileName == NULL) {
        print_usage(options);
        errout(noWarriorFile);
        result = CLP_NOGOOD;
      }
#endif
    }
  }
  return result;
}





